values
  ('00000000-0000-4000-8000-000000000001', 'A relaxed rally after work?', 'Looking for a friendly tennis partner. I’m a little rusty, so a few good rallies and a laugh are the goal. Bring your racket; we can choose a public court together.', 'together', 'tennis', 'Schwabing', 48.1665, 11.5869, 'Lena', '{"mode":"recurring","days":[2,4],"start":"17:30","end":"19:00"}'::jsonb, 'free', null, null, null, null, '2026-10-24T12:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000002', 'A few cuttings, a little more green', 'My pothos has outgrown its windowsill. I have rooted cuttings ready for a new home and can share a few easy care tips.', 'offering', 'plants', 'Maxvorstadt', 48.1508, 11.5706, 'Jonas', '{"mode":"arrangement"}'::jsonb, 'coffee', null, null, null, null, '2026-10-24T11:59:00.000Z'),
  ('00000000-0000-4000-8000-000000000003', 'Help my sofa find its new home', 'Could use an extra pair of hands to carry a small sofa down one flight of stairs. We’ll arrange a meeting point nearby. About 45 minutes of help.', 'looking', 'moving', 'Glockenbachviertel', 48.1262, 11.5695, 'Mila', '{"mode":"date","date":"2027-06-05","start":"14:00","end":"16:00"}'::jsonb, 'paid', 20, 'session', null, null, '2026-10-24T11:58:00.000Z'),
  ('00000000-0000-4000-8000-000000000004', 'Your German, my homemade pasta', 'I’m learning German and love cooking. Let’s make dinner and practise chatting, with plenty of time for questions and second helpings.', 'exchange', 'languages', 'Haidhausen', 48.1309, 11.6028, 'Luca', '{"mode":"recurring","days":[5],"start":"17:30","end":"19:00"}'::jsonb, 'mutual', null, null, 'A homemade pasta lesson and dinner.', 'Friendly German conversation practice.', '2026-10-24T11:57:00.000Z'),
  ('00000000-0000-4000-8000-000000000005', 'Sunday sketchbook club', 'Bring any sketchbook and join a slow afternoon drawing buildings, trees, or whatever catches your eye. All abilities welcome.', 'together', 'drawing', 'Lehel', 48.1424, 11.5923, 'Sophie', '{"mode":"arrangement"}'::jsonb, 'free', null, null, null, null, '2026-10-24T11:56:00.000Z'),
  ('00000000-0000-4000-8000-000000000006', 'Let’s roll along the Isar', 'An easy-paced cycle along the river, with a stop for coffee. Around 15 km, no racing and nobody left behind. Bring your own bike.', 'together', 'cycling', 'Glockenbachviertel', 48.1262, 11.5695, 'Felix', '{"mode":"date","date":"2027-06-08","start":"14:00","end":"16:00"}'::jsonb, 'free', null, null, null, null, '2026-10-24T11:55:00.000Z'),
  ('00000000-0000-4000-8000-000000000007', 'A second pair of hands for a shelf', 'I have the shelf and tools, but would love help measuring and mounting it. A small weekend DIY project with plenty of coffee.', 'looking', 'diy', 'Neuhausen', 48.1553, 11.5354, 'Nora', '{"mode":"recurring","days":[2,4],"start":"17:30","end":"19:00"}'::jsonb, 'coffee', null, null, null, null, '2026-10-24T11:54:00.000Z'),
  ('00000000-0000-4000-8000-000000000008', 'Learn to fold little dumplings', 'I’d love to share my family’s vegetable dumpling recipe with a small group. We can agree on ingredients and dietary needs before meeting.', 'offering', 'cooking', 'Westend', 48.1356, 11.5358, 'Mei', '{"mode":"arrangement"}'::jsonb, 'paid', 12, 'session', null, null, '2026-10-24T11:53:00.000Z'),
  ('00000000-0000-4000-8000-000000000009', 'Plant care for a weekend away', 'Looking for someone nearby to water a few balcony plants while I’m away. Happy to return the favour when you travel.', 'looking', 'plants', 'Sendling', 48.1202, 11.5357, 'Ben', '{"mode":"date","date":"2027-06-11","start":"14:00","end":"16:00"}'::jsonb, 'mutual', null, null, null, null, '2026-10-24T11:52:00.000Z'),
  ('00000000-0000-4000-8000-000000000010', 'Bike tune-up for a drawing lesson', 'I enjoy fixing bikes and can help with a basic check of tyres and chain. In return, I’d love to learn the basics of drawing faces.', 'exchange', 'cycling', 'Neuhausen', 48.1583, 11.5314, 'Amir', '{"mode":"recurring","days":[5],"start":"17:30","end":"19:00"}'::jsonb, 'mutual', null, null, 'A basic bike tune-up.', 'A beginner lesson in drawing faces.', '2026-10-24T11:51:00.000Z'),
  ('00000000-0000-4000-8000-000000000011', 'Beginner tennis, zero pressure', 'Just starting out? Me too. Let’s practise serves and learn together at a nearby court. We can split any court booking costs separately.', 'looking', 'tennis', 'Lehel', 48.1454, 11.5883, 'Hanna', '{"mode":"arrangement"}'::jsonb, 'free', null, null, null, null, '2026-10-24T11:50:00.000Z'),
  ('00000000-0000-4000-8000-000000000012', 'A little German, a little English', 'A relaxed conversation walk through Schwabing. We’ll switch between German and English and help each other find the words.', 'together', 'languages', 'Schwabing', 48.1695, 11.5829, 'Oskar', '{"mode":"date","date":"2027-06-14","start":"14:00","end":"16:00"}'::jsonb, 'free', null, null, null, null, '2026-10-24T11:49:00.000Z'),
  ('00000000-0000-4000-8000-000000000013', 'Borrow my drill for your project', 'My cordless drill is mostly sitting in its box. Happy to lend it for a small project and show you how it works.', 'offering', 'diy', 'Sendling', 48.1202, 11.5357, 'Clara', '{"mode":"recurring","days":[2,4],"start":"17:30","end":"19:00"}'::jsonb, 'free', null, null, null, null, '2026-10-24T11:48:00.000Z'),
  ('00000000-0000-4000-8000-000000000014', 'Soup recipes for balcony herbs', 'I make a lovely seasonal soup and would like to swap a recipe and a portion for a few fresh herbs from your balcony.', 'exchange', 'cooking', 'Maxvorstadt', 48.1538, 11.5666, 'Ella', '{"mode":"arrangement"}'::jsonb, 'mutual', null, null, 'A seasonal soup recipe and a portion to enjoy.', 'A small bunch of fresh balcony herbs.', '2026-10-24T11:47:00.000Z'),
  ('00000000-0000-4000-8000-000000000015', 'Moving boxes, ready for round two', 'Eight sturdy cardboard boxes from my recent move. Flattened and ready to collect at an agreed neighborhood meeting point.', 'offering', 'moving', 'Westend', 48.1386, 11.5318, 'David', '{"mode":"date","date":"2027-06-17","start":"14:00","end":"16:00"}'::jsonb, 'free', null, null, null, null, '2026-10-24T11:46:00.000Z'),
  ('00000000-0000-4000-8000-000000000016', 'Draw the city over a coffee', 'An informal urban sketching meet-up. We’ll find a quiet café, pick a view, and draw for an hour. Bring whatever materials you have.', 'together', 'drawing', 'Haidhausen', 48.1339, 11.5988, 'Ida', '{"mode":"recurring","days":[5],"start":"17:30","end":"19:00"}'::jsonb, 'coffee', null, null, null, null, '2026-10-24T11:45:00.000Z')
